#!/bin/bash
# calm-bridge verifier. Runs the delivered recovery tool against the visible
# artifacts plus live-hidden scenarios generated by the shared gen.py.
# Writes 1 or 0 to /logs/verifier/reward.txt
mkdir -p /logs/verifier

python3 - <<'PY'
import os, sys, json, subprocess

failures = []
def fail(m):
    failures.append(m)
    print("FAIL:", m)

sys.path.insert(0, "/app/files")
from tool import gen as g

DELIV = "/app/recover.py"

def run_recover(db, wal, out):
    r = subprocess.run(["python3", DELIV, "run", db, wal, out],
                       capture_output=True, text=True, timeout=180)
    return r

def exp_csv(rows):
    lines = ["id,name,msisdn,msisdn_d,email,phone,region"]
    for r in rows:
        lines.append(",".join([
            str(r["id"]), r["name"], r["msisdn"],
            "" if r["msisdn_d"] is None else str(r["msisdn_d"]),
            r["email"] or "", r["phone"] or "", r["region"]]))
    return "\n".join(lines) + "\n"

# ------------------------------------------------------------------ deliverable
if not os.path.exists(DELIV):
    fail("deliverable /app/recover.py is missing")
    with open("/logs/verifier/reward.txt", "w") as f:
        f.write("0")
    raise SystemExit(0)

# -------------------------------------------------------------- visible case
vis = "/tmp/vis"
visinfo = g.build_fixture(vis, 2029, 150)
exp_vis = g.expected(visinfo)
try:
    got = json.load(open("/app/merged.json"))
    if got != exp_vis:
        fail("visible merged.json does not match recovered truth "
             "(wrong rows/cleaning/ordering/dedup)")
except Exception as e:
    fail("merged.json unreadable: " + repr(e))

# deliverable set /app/trial_*.csv (numbered 0001..0003)
for si, (no, seed) in enumerate([(1, 1), (2, 2), (3, 3)]):
    path = "/app/trial_{:04d}.csv".format(no)
    if not os.path.exists(path):
        fail("trial csv missing: " + path)
        continue
    tt = "/tmp/tr%d" % si
    tinfo = g.build_fixture(tt, seed, 40)
    got_csv = open(path).read().rstrip("\n")
    want_csv = exp_csv(g.expected(tinfo)).rstrip("\n")
    if got_csv != want_csv:
        fail("trial%d csv mismatch" % no)

# open-fd visible artifact
if not os.path.exists("/app/fd.txt"):
    fail("fd.txt missing (open-file-descriptor recovery)")
else:
    vis_seed = "/tmp/fdseed"
    want = g.build_seed(vis_seed, 71)
    have = open("/app/fd.txt", "rb").read()
    if have != want.encode():
        fail("fd.txt content does not match the recovered descriptor bytes")

# ---------------------------------------------------------------- hidden cases
cases_path = "/tests/hidden/cases.json"
if not os.path.exists(cases_path):
    fail("hidden cases config missing: " + cases_path)
else:
    config = json.load(open(cases_path))
    for c in config["recovery"]:
        h = "/tmp/hf"
        for p in (h + "-wal", h + ".db", h + ".wal"):
            if os.path.exists(p):
                os.remove(p)
        # drop the fixture dir deterministically
        import shutil
        shutil.rmtree(h, ignore_errors=True)
        hinfo = g.build_fixture(
            h, int(c["seed"]), int(c["n"]), malformed_lines=int(c.get("malformed", 0)),
            journal_share=float(c.get("journal_share", 0.35)),
            dup_share=float(c.get("dup_share", 0.12)))
        out = "/tmp/hout.json"
        rc = run_recover(h + "/ledger.db", h + "/ledger.wal", out)
        if rc.returncode != 0:
            fail("hidden seed %s: recover.py exited %d" % (c["seed"], rc.returncode))
            continue
        try:
            got = json.load(open(out))
        except Exception as e:
            fail("hidden seed %s output unreadable: %r" % (c["seed"], e))
            continue
        exp = g.expected(hinfo)
        ids = [r["id"] for r in got]
        if len(ids) != len(set(ids)):
            fail("hidden seed %s: duplicate ids present" % c["seed"])
        if ids != sorted(ids):
            fail("hidden seed %s: not sorted by primary key" % c["seed"])
        if got != exp:
            fail("hidden seed %s mismatch (recovered %d vs expected %d)"
                 % (c["seed"], len(got), len(exp)))

    # hidden fd recovery through the delivered tool
    hseed = "/tmp/hfd"
    g.build_seed(hseed, 42)
    hout = "/tmp/hfd.out"
    r = subprocess.run(["python3", DELIV, "fd", hseed, hout],
                       capture_output=True, text=True)
    if r.returncode != 0 or not os.path.exists(hout):
        fail("hidden fd recovery failed")
    elif open(hout, "rb").read() != g.build_seed("/tmp/hfd_check", 42).encode():
        fail("hidden fd recovery content mismatch")

    # ------------------------------------------------------------------ perf
    scale = "/tmp/scale_p.db"
    g.build_scaled(scale, int(config["perf_nrows"]))
    r = subprocess.run([DELIV, "perf", scale], capture_output=True, text=True)
    if r.returncode != 0:
        fail("perf command failed")
    else:
        try:
            ms = int(r.stdout.strip().split()[-1])
        except ValueError:
            fail("perf did not emit an integer ms value")
            ms = 10 ** 9
        if ms > int(config["perf_threshold_ms"]):
            fail("perf %d ms exceeds threshold %d ms"
                 % (ms, int(config["perf_threshold_ms"])))
        else:
            print("perf ok: %d ms" % ms)

with open("/logs/verifier/reward.txt", "w") as f:
    f.write("1" if not failures else "0")
print("verifier failures:", len(failures))
PY